const CELL_RESOLUTION = 256;

export { DEFAULT_DAMPING, FDTD_REFERENCE_FREQUENCY };

export const FDTD_2D_Defaults = {
  width: 10,
  height: 10,
  cellSize: 10 / CELL_RESOLUTION,
  offsetX: 0,
  offsetY: 0,
  slice: "xz" as FdtdSlice,
};

export interface FDTD_2D_Props {
  width?: number;
  height?: number;
  cellSize?: number;
  offsetX?: number;
  offsetY?: number;
  /** Floor plan (`xz`) or vertical sketch (`xy`). Inferred from the selected surface when omitted. */
  slice?: FdtdSlice;
  /** Air temperature in °C. Default 20, matching the other solvers. */
  temperature?: number;
  /**
   * Walls follow their materials' octave bands in one run (#222), as fitted
   * series-RLC branches, instead of one coefficient at
   * FDTD_REFERENCE_FREQUENCY. Default off.
   */
  frequencyDependentWalls?: boolean;
}

/**
 * Fitted branches per material spectrum, shared by every solver: a fit costs
 * a fraction of a second and the same materials recur across surfaces.
 * Unbounded, which is fine for a scene's handful of materials; a session that
 * fits thousands of spectra would want an eviction policy here.
 */
const rlcFitCache = new Map<string, RlcBranch[]>();

/** The 2D fit of a wall's octave bands (#222), or none for a rigid material. */
export function rlcBranchesForBands(bands: { frequencies: number[]; absorption: number[] }): RlcBranch[] {
  const key = JSON.stringify(bands);
  let branches = rlcFitCache.get(key);
  if (!branches) {
    branches = fitRlcToOctaveBands(bands.frequencies, bands.absorption, { dims: 2 }).branches;
    rlcFitCache.set(key, branches);
  }
  return branches;
}

export interface Uniforms {
  [uniform: string]: IUniform;
}

class FDTD_2D extends Solver {
  gpuCompute!: GPUComputationRenderer;

  /**
   * number of x cells
   */
  nx: number;

  /**
   * number of y cells
   */
  ny: number;
  
  offsetX: number;
  offsetY: number;
  slice: FdtdSlice;
  sliceHeight: number;

  uniforms!: Uniforms;
  mesh!: Mesh;
  editMesh!: Mesh;
  heightmapVariable!: Variable;
  sourcemapVariable!: Variable;
  sourcemap!: DataTexture;
  /**
   * Staircase face weights per wall cell, as `1 − w` (#220), in r and g; the
   * wall's RLC material index plus one in b (#222).
   */
  wallmap!: DataTexture;
  /** See FDTD_2D_Props.frequencyDependentWalls. */
  frequencyDependentWalls: boolean;
  /** Branch-state variables, RLC_TEXTURES of them when frequencyDependentWalls. */
  rlcVariables: Variable[] = [];
  /** (b, bd, bDh, bFh) per branch and material, for the current dt. */
  rlcCoefficients?: DataTexture;
  rlcTable = new RlcMaterialTable();
  zeroShader?: ShaderMaterial;
  readLevelShader!: ShaderMaterial;
  readLevelImage!: Uint8Array;
  readLevelRenderTarget!: WebGLRenderTarget;
  sources!: KeyValuePair<Source>;
  sourceKeys!: string[];
  receivers!: KeyValuePair<Receiver>;
  receiverKeys!: string[];
  walls!: FDTDWall[];
  /**
   * simulation in seconds
   */
  time: number;

  /**
   * simulation time step in seconds
   */
  dt: number;
  width: number;
  height: number;
  cellSize: number;
  numPasses: number;
  waveSpeed: number;
  _temperature: number;
  recording: boolean;
  lastTickMs: number | null;
  clearShader!: ShaderMaterial;
  frame: number;
  messageHandlers: string[][];
  eventListeners: (()=>void)[];
  constructor(props?: FDTD_2D_Props) {
    super(props);
    this.kind = "fdtd-2d";
    this.running = false;
    this.time = 0;
    this.frame = 0;
    this.numPasses = 1;
    this._temperature = props?.temperature ?? 20;
    this.frequencyDependentWalls = props?.frequencyDependentWalls ?? false;
    this.waveSpeed = soundSpeed(this._temperature);
    this.recording = false;
    this.lastTickMs = null;

    const surfaces = [...useContainer.getState().selectedObjects.values()].filter(x=>x.kind==="surface") as Surface[];
    let surface: Surface|null = null;
    props = props || {};
    let inferredDomain: ReturnType<typeof domainFromBox> | null = null;
    if (surfaces.length > 0) {
      surface = surfaces.length > 1 ? surfaces[0].mergeSurfaces(surfaces) : surfaces[0];
      surface.updateMatrixWorld(true);
      surface.mesh.geometry.computeBoundingBox();
      const localBox = surface.mesh.geometry.boundingBox;
      if (localBox) {
        const min = localBox.min.clone().applyMatrix4(surface.mesh.matrixWorld);
        const max = localBox.max.clone().applyMatrix4(surface.mesh.matrixWorld);
        inferredDomain = domainFromBox(
          { min: { x: min.x, y: min.y, z: min.z }, max: { x: max.x, y: max.y, z: max.z } },
          props.slice,
        );
        props.width = inferredDomain.width;
        props.height = inferredDomain.height;
        props.offsetX = inferredDomain.offsetX;
        props.offsetY = inferredDomain.offsetY;
        props.slice = inferredDomain.slice;
      }
    }
    const _width = (props && props.width) || FDTD_2D_Defaults.width;
    const _height = (props && props.height) || FDTD_2D_Defaults.height;

    this.offsetX = (props && props.offsetX) || FDTD_2D_Defaults.offsetX;
    this.offsetY = (props && props.offsetY) || FDTD_2D_Defaults.offsetY;
    this.slice = (props && props.slice) || inferredDomain?.slice || FDTD_2D_Defaults.slice;
    this.sliceHeight = inferredDomain?.sliceHeight ?? 0;

    this.cellSize = (props && props.cellSize) || Math.max(_width, _height) / CELL_RESOLUTION;

    this.nx = Math.ceil(_width / this.cellSize);
    this.ny = Math.ceil(_height / this.cellSize);

    this.width = this.nx * this.cellSize;
    this.height = this.ny * this.cellSize;

    this.dt = 0;
    this.applyWaveSpeed();

    this.sources = {} as KeyValuePair<Source>;
    this.sourceKeys = [] as string[];
    this.receivers = {} as KeyValuePair<Receiver>;
    this.receiverKeys = [] as string[];
    this.walls = [] as FDTDWall[];
    this.messageHandlers = [] as string[][];
    this.eventListeners = [] as (()=>void)[];

    const editGeometry = new PlaneGeometry(this.width, this.height, 1, 1);
    applySliceTransform(editGeometry, {
      slice: this.slice,
      width: this.width,
      height: this.height,
      offsetX: this.offsetX,
      offsetY: this.offsetY,
      sliceHeight: this.sliceHeight,
    });
    const editMaterials = [
      new MeshBasicMaterial({ wireframe: true, side: DoubleSide, color: 0x707070 }),
      new MeshLambertMaterial({ transparent: true, opacity: 0.35, side: DoubleSide, color: 0x707070 })
    ];
    
    this.editMesh = new Mesh(editGeometry, editMaterials[0]);
    this.editMesh.name = "fdtd-2d-edit-mesh";
    this.editMesh.visible = false;
    
    renderer.fdtdItems.add(this.editMesh);
    

    this.fillTexture = this.fillTexture.bind(this);
    this.init = this.init.bind(this);
    this.render = this.render.bind(this);
    this.updateWalls = this.updateWalls.bind(this);
    this.updateSourceTexture = this.updateSourceTexture.bind(this);
    this.addWallsFromSurfaceEdges = this.addWallsFromSurfaceEdges.bind(this);
    this.setWireframeVisible = this.setWireframeVisible.bind(this);
    this.getWireframeVisible = this.getWireframeVisible.bind(this);
    this.toggleWall = this.toggleWall.bind(this);
    this.clear = this.clear.bind(this);
    
    
    this.init();

    this.eventListeners.push(on("RENDERER_UPDATED", () => {
      if (this.running) this.render();
    }));
    
    this.onModeChange(postMessage("GET_EDITOR_MODE")[0]);

    if(surface){
      this.addWallsFromSurfaceEdges(surface);
    }
    

  }
  onModeChange(mode: EditorModes) {
    switch (mode) {
      case EditorModes.OBJECT: { 
        this.editMesh.visible = false;
        this.mesh.visible = true;
      } break;
      case EditorModes.SKETCH: { 
        this.editMesh.visible = false;
        this.mesh.visible = false;
      } break;
      case EditorModes.EDIT: { 
        this.editMesh.visible = true;
        this.mesh.visible = false;
      } break;
      default: break;
    }
  }
  setWidth(width: number) {
    this.nx = Math.ceil(width / this.cellSize);
    this.width = this.nx * this.cellSize;
  }
  setHeight(height: number) {
    this.ny = Math.ceil(height / this.cellSize);
    this.height = this.ny * this.cellSize;
  }
  
  setDimmensions(width: number, height: number) {
    this.setWidth(width);
    this.setHeight(height);
  }
  
  init() {
    this.disposeGpu();
    const geometry = new PlaneGeometry(this.width, this.height, this.nx - 1, this.ny - 1);
    geometry.name = "fdtd-2d-plane-geometry";
    applySliceTransform(geometry, {
      slice: this.slice,
      width: this.width,
      height: this.height,
      offsetX: this.offsetX,
      offsetY: this.offsetY,
      sliceHeight: this.sliceHeight,
    });
    const heightmap = { value: null };
    // The display is unlit (#240): its shaders read the height and the colour
    // scale, plus three's fog uniforms (log depth and clipping planes are
    // supplied by the renderer), and nothing more.
    const uniforms = UniformsUtils.merge([
      UniformsLib.fog,
      {
        colorBrightness: { value: 10 },
        heightmap
      }
    ]);
    const vertexShader = shaders.waterVert;
    // One constant for the display's half range, in TypeScript and GLSL (#224).
    const fragmentShader = `#define DISPLAY_HALF_RANGE ${DISPLAY_HALF_RANGE.toFixed(1)}\n${shaders.waterFrag}`;
    const side = DoubleSide;
    const material = new ShaderMaterial({
      uniforms,
      vertexShader,
      fragmentShader,
      side,
      name: "fdtd-2d-material"
    });

    this.uniforms = material.uniforms;
    this.mesh = new Mesh(geometry, material);

    this.mesh.matrixAutoUpdate = false;
    this.mesh.updateMatrix();
    // this.mesh.scale.setScalar(this.width / this.nx);
    (this.mesh.material as ShaderMaterial).wireframe = false;
    this.mesh.matrixAutoUpdate = true;
    this.mesh.scale.setZ(0.01);
    renderer.fdtdItems.add(this.mesh);

    this.gpuCompute = new GPUComputationRenderer(this.nx, this.ny, renderer.renderer as WebGLRenderer);

    let heightmapInit = this.gpuCompute.createTexture();
    this.sourcemap = this.gpuCompute.createTexture();
    // All zero, which is weight 1 everywhere until updateWalls writes a wall.
    this.wallmap = this.gpuCompute.createTexture();
    this.fillSourceTexture();
    this.updateSourceTexture();
    this.fillTexture(heightmapInit);
    const rlcTextures = this.frequencyDependentWalls ? RLC_TEXTURES : 0;
    this.heightmapVariable = this.gpuCompute.addVariable(
      "heightmap",
      withRlc(withGhostGainDefine(shaders.heightMapFrag), rlcTextures),
      heightmapInit,
    );
    // Branch state (#222): zero to start, every pass reading the previous
    // frame's heightmap and its own previous state.
    this.rlcVariables = [];
    for (let k = 0; k < rlcTextures; k++) {
      this.rlcVariables.push(
        this.gpuCompute.addVariable(`rlc${k}`, rlcBranchShader(k), this.gpuCompute.createTexture()),
      );
    }
    this.gpuCompute.setVariableDependencies(this.heightmapVariable, [
      this.heightmapVariable,
      ...this.rlcVariables,
    ]);
    for (const variable of this.rlcVariables) {
      this.gpuCompute.setVariableDependencies(variable, [this.heightmapVariable, variable]);
      (variable.material as ShaderMaterial).uniforms["sourcemap"] = { value: this.sourcemap };
      (variable.material as ShaderMaterial).uniforms["wallmap"] = { value: this.wallmap };
    }

    (this.heightmapVariable.material as ShaderMaterial).uniforms["sourcemap"] = { value: this.sourcemap };
    (this.heightmapVariable.material as ShaderMaterial).uniforms["wallmap"] = { value: this.wallmap };

    (this.heightmapVariable.material as ShaderMaterial).uniforms["mousePos"] = { value: new Vector2(5, 5) };

    (this.heightmapVariable.material as ShaderMaterial).uniforms["mouseSize"] = { value: 0.0 };

    // Numerical sponge on velocity — not air absorption and not a Surface
    // material. Off by default now that walls absorb; see DEFAULT_DAMPING for
    // what it used to impose and why nothing below 1 is safe at every grid.
    (this.heightmapVariable.material as ShaderMaterial).uniforms["damping"] =
      { value: DEFAULT_DAMPING };

    (this.heightmapVariable.material as ShaderMaterial).uniforms["courantSq"] = { value: 0 };
    this.applyWaveSpeed();

    (this.heightmapVariable.material as ShaderMaterial).uniforms["heightCompensation"] = { value: 0 };

    (this.heightmapVariable.material as ShaderMaterial).uniforms["cell_size"] = { value: this.cellSize };

    (this.heightmapVariable.material as ShaderMaterial).uniforms["inv_cell_size"] = { value: 1 / this.cellSize };

    this.rlcCoefficients?.dispose();
    this.rlcCoefficients = undefined;
    this.updateRlcCoefficients();

    const error = this.gpuCompute.init();
    if (error !== null) {
      console.error(error);
    }

    this.clearShader = this.gpuCompute["createShaderMaterial"](shaders.clearFrag, { clearTexture: { value: null } });
    this.zeroShader = this.gpuCompute["createShaderMaterial"]("void main() { gl_FragColor = vec4(0.0); }", {});

    this.readLevelShader = this.gpuCompute["createShaderMaterial"](shaders.readLevelFrag, {
      point1: { value: new Vector2() },
      levelTexture: { value: null },
      cell_size: { value: this.cellSize },
      inv_cell_size: { value: 1 / this.cellSize }
    });

    // Create a 4x1 pixel image and a render target (Uint8, 4 channels, 1 byte per channel) to read water height and orientation
    this.readLevelImage = new Uint8Array(4 * 1 * 4);

    this.readLevelRenderTarget = new WebGLRenderTarget(4, 1, {
      wrapS: ClampToEdgeWrapping,
      wrapT: ClampToEdgeWrapping,
      minFilter: NearestFilter,
      magFilter: NearestFilter,
      format: RGBAFormat,
      type: UnsignedByteType,
      stencilBuffer: false,
      depthBuffer: false
    });
    

    this.render();
    this.clear();
  }
  editSize() {
    // this.mesh.visible = false;
  }
  disposeGpu() {
    if (this.mesh) {
      renderer.fdtdItems.remove(this.mesh);
      this.mesh.geometry.dispose();
      const material = this.mesh.material;
      if (Array.isArray(material)) material.forEach((m) => m.dispose());
      else material.dispose();
    }
    this.readLevelRenderTarget?.dispose();
    this.sourcemap?.dispose();
    this.wallmap?.dispose();
    this.clearShader?.dispose();
    this.readLevelShader?.dispose();
    this.zeroShader?.dispose();
    this.rlcCoefficients?.dispose();
    this.rlcCoefficients = undefined;
    disposeGpuCompute(this.gpuCompute);
  }

  dispose() {
    this.stop();
    this.disposeGpu();
    if (this.editMesh) {
      renderer.fdtdItems.remove(this.editMesh);
      this.editMesh.geometry.dispose();
      const material = this.editMesh.material;
      if (Array.isArray(material)) material.forEach((m) => m.dispose());
      else material.dispose();
    }
    this.eventListeners.forEach((fn) => fn());
    this.eventListeners = [];
    for (let i = 0; i < this.messageHandlers.length; i++) {
      removeMessageHandler(this.messageHandlers[i][0], this.messageHandlers[i][1]);
    }
    this.messageHandlers = [] as string[][];
  }
  run() {
    this.running = true;
    this.lastTickMs = null;
    renderer.fdtd2drunning = true;
  }
  stop() {
    this.running = false;
    this.lastTickMs = null;
    renderer.fdtd2drunning = false;
  }

  get temperature() {
    return this._temperature;
  }
  set temperature(value: number) {
    this._temperature = value;
    this.applyWaveSpeed();
  }
  get c() {
    return soundSpeed(this._temperature);
  }
  /** Keep waveSpeed, dt, and courantSq on the CFL 1/√2 locus. */
  applyWaveSpeed() {
    this.waveSpeed = this.c;
    if (this.cellSize > 0) {
      this.dt = computeTimestep(this.cellSize, this.waveSpeed);
    }
    const material = this.heightmapVariable?.material as ShaderMaterial | undefined;
    if (material?.uniforms?.courantSq && this.cellSize > 0) {
      material.uniforms.courantSq.value = (this.waveSpeed * this.dt / this.cellSize) ** 2;
    }
    // The branches are discretised for dt (#222).
    this.updateRlcCoefficients();
  }

  /**
   * Rebuild the RLC coefficient texture for the current materials and dt,
   * and bind it, with the Courant number, to every pass that reads it.
   */
  updateRlcCoefficients() {
    if (!this.frequencyDependentWalls || !this.heightmapVariable || !(this.dt > 0)) return;
    const rows = Math.max(1, this.rlcTable.size);
    const data = this.rlcTable.texels(this.dt);
    if (!this.rlcCoefficients || this.rlcCoefficients.image.height !== rows) {
      this.rlcCoefficients?.dispose();
      this.rlcCoefficients = new DataTexture(data, RLC_MAX_BRANCHES, rows, RGBAFormat, FloatType);
      this.rlcCoefficients.minFilter = NearestFilter;
      this.rlcCoefficients.magFilter = NearestFilter;
    } else {
      (this.rlcCoefficients.image.data as Float32Array).set(data);
    }
    this.rlcCoefficients.needsUpdate = true;
    for (const variable of [this.heightmapVariable, ...this.rlcVariables]) {
      const uniforms = (variable.material as ShaderMaterial).uniforms;
      uniforms["rlcCoefficients"] = { value: this.rlcCoefficients };
      uniforms["rlcMaterialCount"] = { value: rows };
      uniforms["courant"] = { value: this.courant };
    }
  }

  /**
   * Switch frequency-dependent walls (#222) on or off. The GPU passes are
   * rebuilt, so the field restarts from rest.
   */
  setFrequencyDependentWalls(on: boolean) {
    if (on === this.frequencyDependentWalls) return;
    this.frequencyDependentWalls = on;
    this.init();
    this.updateWalls();
  }

  get sampleRate() {
    return sampleRateFromDt(this.dt);
  }

  startRecording() {
    this.recording = true;
    this.lastTickMs = null;
    const rate = this.sampleRate;
    for (const key of this.sourceKeys) {
      if (this.sources[key]) this.sources[key].fdtdSampleRate = rate;
    }
    for (const key of this.receiverKeys) {
      if (this.receivers[key]) this.receivers[key].fdtdSampleRate = rate;
    }
  }

  stopRecording() {
    this.recording = false;
  }
  // save() {
  //   return pickProps(["name", "uuid", "width", "height", "offsetX", "offsetY", "cellSize"], this);
  // }
  setWireframeVisible(show: boolean) {
    (this.mesh.material as ShaderMaterial).wireframe = show;
  }
  getWireframeVisible() {
    return (this.mesh.material as ShaderMaterial).wireframe;
  }
  addSource(source: Source) {
    this.sourceKeys = [...new Set(this.sourceKeys.concat(source.uuid))];
    this.sources[source.uuid] = source;
  }
  removeSource(id: string) {
    const source = this.sources[id];
    if (!source) return;
    this.vacateSourceCell(source.position);
    delete this.sources[id];
    this.sourceKeys = this.sourceKeys.filter((x) => x !== id);
  }

  private planeCellIndex(point: { x: number; y: number; z: number }) {
    return gridCellIndex(point, this.slice, {
      offsetX: this.offsetX,
      offsetY: this.offsetY,
      cellSize: this.cellSize,
      nx: this.nx,
      ny: this.ny,
    });
  }

  private vacateSourceCell(point: { x: number; y: number; z: number }) {
    const pixels = this.sourcemap?.image?.data;
    if (!pixels) return;
    const index = this.planeCellIndex(point);
    if (index == null) return;
    writeFieldPixel(pixels, index, vacatedSourcePixel());
    this.sourcemap.needsUpdate = true;
  }
  addReceiver(receiver: Receiver) {
    this.receiverKeys = [...new Set(this.receiverKeys.concat(receiver.uuid))];
    this.receivers[receiver.uuid] = receiver;
  }
  removeReceiver(id: string) {
    if (this.receivers[id]) {
      delete this.receivers[id];
      this.receiverKeys = this.receiverKeys.filter((x) => x !== id);
    }
  }
  addWall(props: FDTDWallProps) {
    const x1 = clamp(Math.floor((props.x1 - this.offsetX) / this.cellSize), 0, this.nx - 1);
    const y1 = clamp(Math.floor((props.y1 - this.offsetY) / this.cellSize), 0, this.ny - 1);
    const x2 = clamp(Math.floor((props.x2 - this.offsetX) / this.cellSize), 0, this.nx - 1);
    const y2 = clamp(Math.floor((props.y2 - this.offsetY) / this.cellSize), 0, this.ny - 1);
    this.walls.push(new FDTDWall({ x1, y1, x2, y2, absorption: props.absorption }));
    this.updateWalls();
  }
  addWallsFromSurfaceEdges(surface: Surface) {
    surface.updateMatrixWorld(true);
    // One coefficient stands in for the curve — see FDTD_REFERENCE_FREQUENCY.
    // A surface with no material reads 0, which is the rigid wall this solver
    // gave every surface before #199.
    const absorption = surface.absorptionFunction?.(FDTD_REFERENCE_FREQUENCY) ?? 0;
    // The whole spectrum as well, for frequency-dependent walls (#222).
    const spectrum = surface.acousticMaterial?.absorption as Record<string, number> | undefined;
    const frequencies = spectrum ? Object.keys(spectrum).map(Number).sort((a, b) => a - b) : [];
    const bands = frequencies.length > 0
      ? { frequencies, absorption: frequencies.map((f) => spectrum![String(f)]) }
      : undefined;
    const edges = surface.edges;
    edges.updateMatrixWorld(true);
    const positionAttr = (edges.geometry as BufferGeometry).getAttribute('position');
    const a = new Vector3();
    const b = new Vector3();
    for (let i = 0; i < positionAttr.count; i += 2) {
      a.fromBufferAttribute(positionAttr, i).applyMatrix4(edges.matrixWorld);
      b.fromBufferAttribute(positionAttr, i + 1).applyMatrix4(edges.matrixWorld);
      const pa = worldToPlane(a, this.slice);
      const pb = worldToPlane(b, this.slice);
      const x1 = clamp(Math.floor((pa.u - this.offsetX) / this.cellSize), 0, this.nx - 1);
      const y1 = clamp(Math.floor((pa.v - this.offsetY) / this.cellSize), 0, this.ny - 1);
      const x2 = clamp(Math.floor((pb.u - this.offsetX) / this.cellSize), 0, this.nx - 1);
      const y2 = clamp(Math.floor((pb.v - this.offsetY) / this.cellSize), 0, this.ny - 1);
      this.walls.push(new FDTDWall({ x1, y1, x2, y2, absorption, bands }));
    }
    this.updateWalls();
  }

  fillSourceTexture() {
    const pixels = this.sourcemap.image.data;
    if (!pixels) return;
    let p = 0;
    for (let j = 0; j < this.ny; j++) {
      for (let i = 0; i < this.nx; i++) {
        pixels[p + 0] = REST_PRESSURE;
        pixels[p + 1] = REST_VELOCITY;
        pixels[p + 2] = AIR_CHANNEL;
        pixels[p + 3] = 1;
        p += 4;
      }
    }
  }

  toggleWall(index: number) {
    if (this.walls[index]) {
      this.walls[index].enabled = !this.walls[index].enabled;
      this.updateWalls();
    }
  }

  /** Courant number the field runs at. The CFL locus puts it at 1/√2. */
  get courant(): number {
    return this.cellSize > 0 ? (this.waveSpeed * this.dt) / this.cellSize : 0;
  }

  /**
   * Highest frequency the walls deliver their coefficient at, within about
   * 0.05 in α. Above it they read as more reflective than their materials.
   */
  get impedanceFrequencyLimit(): number {
    return this.cellSize > 0
      ? this.waveSpeed / (FDTD_CELLS_PER_WAVELENGTH_FOR_IMPEDANCE * this.cellSize)
      : 0;
  }

  updateWalls() {
    const data = this.sourcemap.image.data;
    if (!data) return;
    // The staircase weights are a correction on top of the walls, so a
    // missing wallmap must not stop absorption itself from updating: the
    // sourcemap is still written, and the walls run uncorrected.
    const weights = this.wallmap?.image?.data;
    if (!weights) {
      console.warn('FDTD 2D: wallmap missing; walls are written without staircase correction (#220).');
    }
    // Materials are re-indexed from scratch, so a wall that changed or went
    // away leaves nothing behind in the table (#222).
    this.rlcTable = new RlcMaterialTable();
    for (let i = 0; i < this.walls.length; i++) {
      const wall = this.walls[i];
      if (wall.shouldClearPreviousCells) {
        for (let j = 0; j < wall.previousCells.length; j++) {
          const index = 4 * (wall.previousCells[j][1] * this.nx + wall.previousCells[j][0]);
          data[index + 2] = AIR_CHANNEL;
          if (weights) {
            weights[index + 0] = 0;
            weights[index + 1] = 0;
            weights[index + 2] = 0;
          }
        }
        wall.shouldClearPreviousCells = false;
      }
      const channel = wallChannelFor(wall, this.courant);
      const texel = wallmapTexelFor(wall);
      const material = rlcWallmapChannel(this.rlcMaterialFor(wall));
      for (let j = 0; j < wall.cells.length; j++) {
        const index = 4 * (wall.cells[j][1] * this.nx + wall.cells[j][0]);
        data[index + 2] = channel;
        if (weights) {
          weights[index + 0] = texel.r;
          weights[index + 1] = texel.g;
          weights[index + 2] = material;
        }
      }
    }
    this.sourcemap.needsUpdate = true;
    if (weights) this.wallmap.needsUpdate = true;
    this.updateRlcCoefficients();
  }

  /**
   * A wall's RLC material index (#222), or null to keep its single
   * coefficient: frequency-dependent walls off, a disabled wall, a wall with
   * no spectrum, or a spectrum that is rigid in every band.
   */
  private rlcMaterialFor(wall: FDTDWall): number | null {
    if (!this.frequencyDependentWalls || !wall.enabled || !wall.bands) return null;
    const branches = rlcBranchesForBands(wall.bands);
    return branches.length > 0 ? this.rlcTable.indexFor(branches) : null;
  }

  updateSourceTexture() {
    const pixels = this.sourcemap.image.data;
    if (!pixels) return;
    for (let i = 0; i < this.sourceKeys.length; i++) {
      const source = this.sources[this.sourceKeys[i]];
      source.updateWave(this.time, this.frame, this.dt);
      const index = this.planeCellIndex(source.position);

      // A soft source (#224): the cell it left just stops being forced.
      // Vacate before writing, so a move within one cell keeps its forcing.
      if (source.shouldClearPreviousPosition) {
        const prevIndex = this.planeCellIndex({
          x: source.previousX,
          y: source.previousY,
          z: source.previousZ,
        });
        if (prevIndex != null && prevIndex !== index) {
          writeFieldPixel(pixels, prevIndex, vacatedSourcePixel());
        }
        source.shouldClearPreviousPosition = false;
        source.updatePreviousPosition();
      }
      if (index != null) {
        // Forced by the signal's difference, which carries no DC (#224).
        writeFieldPixel(pixels, index, softSourcePixel(source.velocity));
      }
    }
    this.sourcemap.needsUpdate = true;
  }
  fillTexture(texture: DataTexture) {
    const pixels = texture.image.data;
    if (!pixels) return;
    let p = 0;
    for (let j = 0; j < this.ny; j++) {
      for (let i = 0; i < this.nx; i++) {
        pixels[p + 0] = REST_PRESSURE;
        pixels[p + 1] = REST_VELOCITY;
        // The previous velocity, which frequency-dependent walls read (#222).
        pixels[p + 2] = REST_VELOCITY;
        pixels[p + 3] = 1;
        p += 4;
      }
    }
  }
  readReceiverLevels() {
    const currentRenderTarget = this.gpuCompute.getCurrentRenderTarget(this.heightmapVariable);
    this.readLevelShader.uniforms["levelTexture"].value = currentRenderTarget["texture"];
    for (let i = 0; i < this.receiverKeys.length; i++) {
      const key = this.receiverKeys[i];
      if (this.receivers[key]) {
        const plane = worldToPlane(this.receivers[key].position, this.slice);
        const u = (plane.u - this.offsetX) / this.width;
        const v = (plane.v - this.offsetY) / this.height;
        this.readLevelShader.uniforms["point1"].value.set(u, v);
        this.gpuCompute.doRenderTarget(this.readLevelShader, this.readLevelRenderTarget);
        (renderer.renderer as WebGLRenderer).readRenderTargetPixels(
          this.readLevelRenderTarget,
          0,
          0,
          4,
          1,
          this.readLevelImage
        );
        const pixels = new Float32Array(this.readLevelImage.buffer);
        const level = pixels[0];
        // Zero-centred state (#224), in display units of the half range.
        this.receivers[key].fdtdSamples.push(level / DISPLAY_HALF_RANGE);
      }
    }
  }
  clear() {
    const currentRenderTarget = this.gpuCompute.getCurrentRenderTarget(this.heightmapVariable);
    const alternateRenderTarget = this.gpuCompute.getAlternateRenderTarget(this.heightmapVariable);
    this.clearShader.uniforms["clearTexture"].value = currentRenderTarget["texture"];
    this.gpuCompute.doRenderTarget(this.clearShader, alternateRenderTarget);
    this.clearShader.uniforms["clearTexture"].value = alternateRenderTarget["texture"];
    this.gpuCompute.doRenderTarget(this.clearShader, currentRenderTarget);
    // Branch state back to rest with the field (#222).
    if (this.zeroShader) {
      for (const variable of this.rlcVariables) {
        this.gpuCompute.doRenderTarget(this.zeroShader, this.gpuCompute.getCurrentRenderTarget(variable));
        this.gpuCompute.doRenderTarget(this.zeroShader, this.gpuCompute.getAlternateRenderTarget(variable));
      }
    }
    // Sources restart from rest too, so the first forcing after a clear is
    // their first sample, not a jump from where they were (#224).
    for (const key of this.sourceKeys) {
      const source = this.sources[key];
      if (source) {
        source.value = 0;
        source.previousValue = 0;
        source.velocity = 0;
      }
    }
    this.time = 0;
    this.frame = 0;
    this.lastTickMs = null;
  }
  render(nowMs: number = (typeof performance !== "undefined" ? performance.now() : 0)) {
    const wallDt = this.lastTickMs == null ? 0 : (nowMs - this.lastTickMs) / 1000;
    this.lastTickMs = nowMs;
    const passes = passesForElapsed({
      wallDt,
      dt: this.dt,
      displayPasses: this.numPasses,
      recording: this.recording,
    });
    for (let i = 0; i < passes; i++) {
      this.updateSourceTexture();

      this.heightmapVariable.material["uniforms"]["sourcemap"].value = this.sourcemap;
      this.heightmapVariable.material["uniforms"]["wallmap"].value = this.wallmap;
      for (const variable of this.rlcVariables) {
        variable.material["uniforms"]["sourcemap"].value = this.sourcemap;
        variable.material["uniforms"]["wallmap"].value = this.wallmap;
      }

      // Do the gpu computation
      this.gpuCompute.compute();

      if (this.recording) {
        for (let j = 0; j < this.sourceKeys.length; j++){
          this.sources[this.sourceKeys[j]].recordSample();
        }
        this.readReceiverLevels();
      }

      this.time += this.dt;
      this.frame += 1;
    }

    // Get compute output in custom uniform
    this.uniforms["heightmap"].value = this.gpuCompute.getCurrentRenderTarget(this.heightmapVariable)["texture"];
  }
  onParameterConfigFocus() {}
  onParameterConfigBlur() {}
}

export { FDTD_2D };

export default FDTD_2D;

